insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('fa781c83-0ced-4d56-a331-02766ca122a9', 'ceb32f3a-012d-47b9-a2ea-7a5b65a11924', $$functie f(x) = 2ˣ + 2⁻²ˣ met minimum (figuur 1)$$,
   $$wiskunde-b-vwo-2017-ii-twee-machten-van-2-context1.png$$,
   $$De functie f is gegeven door: f(x) = 2ˣ + 2⁻²ˣ
In figuur 1 is een deel van de grafiek van f weergegeven.
De functie heeft één extreme waarde en dat is een minimum.
figuur 1: grafiek van f$$, 'inline'),
  ('485fb30a-5b8d-4fa8-a94b-770bee6cb8a6', 'ceb32f3a-012d-47b9-a2ea-7a5b65a11924', $$grijze gebieden met gelijke oppervlakte (figuur 2 en 3)$$,
   $$wiskunde-b-vwo-2017-ii-twee-machten-van-2-context2.png$$,
   $$In figuur 2 is het gebied grijs gemaakt dat wordt begrensd door de grafiek van f, de x-as en de lijnen met vergelijkingen x = −1 en x = 1.
In figuur 3 is het rechthoekige gebied grijs gemaakt dat wordt begrensd door de x-as en de lijnen met vergelijkingen x = −1, x = 1 en y = k.
De waarde van k is zo gekozen dat het grijze gebied uit figuur 2 en het grijze gebied uit figuur 3 dezelfde oppervlakte hebben.
figuur 2: grijs gebied onder de grafiek van f tussen x = −1 en x = 1
figuur 3: grijze rechthoek tussen x = −1, x = 1, de x-as en y = k$$, 'inline'),
  ('cec35c4b-bb97-4eb0-adee-bb48611296ce', 'ceb32f3a-012d-47b9-a2ea-7a5b65a11924', $$punten A, Q en P met AP⃗ loodrecht op AQ⃗$$,
   $$wiskunde-b-vwo-2017-ii-twee-machten-van-2-context3.png$$,
   $$Op de grafiek van f liggen de punten A(1, 2¼) en Q(2, 4¹⁄₁₆). Ook ligt op de grafiek van f het punt P. Gegeven is dat de vectoren AP⃗ en AQ⃗ loodrecht op elkaar staan.$$, 'inline'),
  ('253f0e34-df3b-43d9-a7db-ab10fc755187', '7abf82ce-60ce-481c-ade3-df730f0855ff', $$functie f(x) = 4e²⁻ˣ + |8 − 4x| met knik in P en raaklijnen k en m (figuur 1)$$,
   $$wiskunde-b-vwo-2017-ii-een-grafiek-met-een-knik-context1.png$$,
   $$De functie f is gegeven door:
f(x) = 4e²⁻ˣ + |8 − 4x|
De grafiek heeft een knik in het punt P. Dit punt verdeelt de grafiek in twee delen. De raaklijn in P aan het linkerdeel van de grafiek van f is lijn m. De raaklijn in P aan het rechterdeel van de grafiek van f is lijn k. In figuur 1 zijn de grafiek van f en de raaklijnen k en m weergegeven. Lijn k is evenwijdig aan de x-as. De hoek die de twee raaklijnen maken is ook in figuur 1 aangegeven.
figuur 1: grafiek van f met de raaklijnen k en m in P$$, 'inline'),
  ('c3b3fa48-f856-4ca6-b93d-a736f40bb9f2', '7abf82ce-60ce-481c-ade3-df730f0855ff', $$scheve asymptoot van de grafiek van f (figuur 2)$$,
   $$wiskunde-b-vwo-2017-ii-een-grafiek-met-een-knik-context2.png$$,
   $$De grafiek van f heeft een asymptoot.
Deze is in figuur 2 aangegeven.
figuur 2: grafiek van f met een gestippelde scheve asymptoot$$, 'inline'),
  ('f100600b-9d3c-4bd6-821f-1b1f736ae1ac', '93fd5b8c-0bad-4996-9a63-47c900d80af8', $$punten A en B op de cirkel x² + (y − 3)² = 25 en driehoek ABC (figuur)$$,
   $$wiskunde-b-vwo-2017-ii-driehoek-in-cirkel-context1.png$$,
   $$In een assenstelsel liggen de punten A(4, 0) en B(0, −2) op de cirkel met vergelijking x² + (y − 3)² = 25.
We bekijken in deze opgave driehoeken ABC met punt C op de grote cirkelboog AB.
Zie de figuur.
figuur: cirkel met de grijze driehoek ABC$$, 'inline'),
  ('58e5c194-e9b4-4da4-9760-69f48dbbe361', '93fd5b8c-0bad-4996-9a63-47c900d80af8', $$driehoek ABC rechthoekig$$,
   $$wiskunde-b-vwo-2017-ii-driehoek-in-cirkel-context2.png$$,
   $$Er zijn twee plaatsen van C op de cirkel waarbij driehoek ABC een rechthoekige driehoek is.$$, 'inline'),
  ('5c2fd04e-eb1c-4f5c-81c1-9a8685eeee40', '93fd5b8c-0bad-4996-9a63-47c900d80af8', $$driehoek ABC gelijkbenig met top A$$,
   $$wiskunde-b-vwo-2017-ii-driehoek-in-cirkel-context3.png$$,
   $$Voor een bepaalde plaats van C op de cirkel is driehoek ABC een gelijkbenige driehoek met top A, dus met AB = AC.$$, 'inline'),
  ('350524a8-2b35-4e69-b81b-1b3808337b8e', '30918390-1704-49a2-afc7-d9bbe96bd22e', $$waterstraal uit een cirkelvormige kraanopening (figuur 1)$$,
   $$wiskunde-b-vwo-2017-ii-straal-van-een-waterstraal-context1.png$$,
   $$In deze opgave kijken we naar water dat uit een cirkelvormige kraanopening stroomt.
In figuur 1 is de vorm van de waterstraal getekend. Op elke hoogte is de horizontale doorsnede van de waterstraal een cirkel. De straal van die cirkel wordt naar beneden toe steeds kleiner.
Op hoogte h heeft de horizontale doorsnede straal r en is de stroomsnelheid van het water v. De kraanopening heeft straal r₀ en bevindt zich op hoogte h₀.
De snelheid waarmee het water uit de kraan stroomt, is v₀.
Het hoogteverschil h₀ − h geven we aan met x.
figuur 1: waterstraal met cirkel op hoogte h₀ met straal r₀ en stroomsnelheid v₀ en cirkel op hoogte h met straal r en stroomsnelheid v; x = h₀ − h$$, 'inline'),
  ('98c04316-8953-43ba-be80-29383cdf5d4a', '30918390-1704-49a2-afc7-d9bbe96bd22e', $$eenheden$$,
   $$wiskunde-b-vwo-2017-ii-straal-van-een-waterstraal-context2.png$$,
   $$In de formules van deze opgave is meter de eenheid van lengte en meter per seconde de eenheid van snelheid.$$, 'inline'),
  ('8846a394-09ef-4ed8-96d4-f0c8f28c2cd5', '30918390-1704-49a2-afc7-d9bbe96bd22e', $$formule 1: wet van behoud van energie$$,
   $$wiskunde-b-vwo-2017-ii-straal-van-een-waterstraal-context3.png$$,
   $$Uit de (natuurkundige) Wet van behoud van energie volgt:
v₀² + 2gh₀ = v² + 2gh (1)
Hierin is g de valversnelling van 9,81 m/s².$$, 'inline'),
  ('3c74ba0a-0be0-4398-9cab-81030d32ed1c', '30918390-1704-49a2-afc7-d9bbe96bd22e', $$formule 2$$,
   $$wiskunde-b-vwo-2017-ii-straal-van-een-waterstraal-context4.png$$,
   $$De hoeveelheid water die per seconde op een bepaalde hoogte voorbijstroomt, is voor elke hoogte gelijk. Hieruit is af te leiden:
r₀² · v₀ = r² · v (2)$$, 'inline'),
  ('861cc6b3-2811-410a-a8cb-e864f5e50542', '30918390-1704-49a2-afc7-d9bbe96bd22e', $$formule 3 voor de straal r$$,
   $$wiskunde-b-vwo-2017-ii-straal-van-een-waterstraal-context5.png$$,
   $$Door formule 1 en formule 2 te combineren kan worden aangetoond:
r = r₀ · ⁴√(v₀²/(v₀² + 2gx)) (3)$$, 'inline'),
  ('b4501b32-e095-4123-93d9-2813bc99d38a', '30918390-1704-49a2-afc7-d9bbe96bd22e', $$kraan met diameter 2 cm en v₀ = 0,5 m/s (figuur 2)$$,
   $$wiskunde-b-vwo-2017-ii-straal-van-een-waterstraal-context6.png$$,
   $$Een bepaalde kraan heeft een opening met een diameter van 2 cm. De opening bevindt zich 30 cm boven een oppervlak. De kraan wordt zo ver opengedraaid dat v₀ = 0,5 m/s.
In figuur 2 is voor deze waterkraan de grafiek getekend die het verband weergeeft tussen het hoogteverschil x en de straal r.
figuur 2: grafiek van r tegen x, van r = 0,01 bij x = 0 tot x = 0,3$$, 'inline'),
  ('c64e698c-7130-45bf-a29a-0861a01f8a68', '30918390-1704-49a2-afc7-d9bbe96bd22e', $$wenteling om de x-as geeft de waterstraal$$,
   $$wiskunde-b-vwo-2017-ii-straal-van-een-waterstraal-context7.png$$,
   $$Als deze grafiek wordt gewenteld om de horizontale x-as, ontstaat de vorm van de waterstraal ( 90 graden linksom gedraaid).
De inhoud van het omwentelingslichaam is gelijk aan de hoeveelheid water waaruit de waterstraal op een bepaald moment bestaat.$$, 'inline'),
  ('5d3cff12-9ab2-467b-aaf9-31c8ea73b29d', '990a23b7-d08e-4f78-a325-6472353608c5', $$cirkels c₁ en c₂ die raken in R (figuur)$$,
   $$wiskunde-b-vwo-2017-ii-cirkels-context1.png$$,
   $$Gegeven zijn de cirkels c₁ en c₂. Cirkel c₁ heeft straal ½ en middelpunt O. Het middelpunt van cirkel c₂ ligt op de positieve y-as.
Cirkel c₁ ligt binnen cirkel c₂. Deze twee cirkels raken elkaar in het punt R(0, −½).
Zie de figuur.
figuur: de cirkels c₁ en c₂ met de punten P, Q en R$$, 'inline'),
  ('1e7791cf-23a0-461e-99e6-2e1f83f0d60e', '990a23b7-d08e-4f78-a325-6472353608c5', $$bewegende punten P en Q en de gegevens over hun beweging$$,
   $$wiskunde-b-vwo-2017-ii-cirkels-context2.png$$,
   $$Er zijn twee bewegende punten, P en Q. Punt P draait rond over cirkel c1, punt Q draait rond over cirkel c2. In de figuur zijn de posities van P en Q op een bepaald tijdstip weergegeven. Verder is gegeven: − Op t = 0 bevinden de punten P en Q zich in R. − Beide punten bewegen tegen de wijzers van de klok in. − Beide punten bewegen met constante snelheid. − De snelheid van P is gelijk aan de snelheid van Q. − Op t = 12 bevindt punt Q zich, sinds t = 0, voor het eerst weer in R. − Op t = 12 heeft punt P precies vier maal c1 doorlopen.$$, 'inline'),
  ('60007207-7e81-4e26-b717-e07555e7d3d4', '990a23b7-d08e-4f78-a325-6472353608c5', $$formule y_Q = k + l · sin(m(t − n))$$,
   $$wiskunde-b-vwo-2017-ii-cirkels-context3.png$$,
   $$De y-coördinaat van punt Q wordt gegeven door een formule van de vorm:
y_Q = k + l · sin(m(t − n))$$, 'inline'),
  ('25de4375-d958-464e-93cf-b958451ee49a', 'e383fe93-6229-4ade-8cb0-22a4ce7dac7b', $$vergelijking van Arrhenius$$,
   $$wiskunde-b-vwo-2017-ii-de-vergelijking-van-arrhenius-context1.png$$,
   $$Om een chemische reactie tot stand te brengen is een bepaalde hoeveelheid activeringsenergie nodig. De Zweedse scheikundige en Nobelprijswinnaar Svante Arrhenius heeft een vergelijking opgesteld die het verband aangeeft tussen het aantal reagerende moleculen, de temperatuur en de activeringsenergie:
k = A · e^(−(E/(8,314T)))
Hierin is
– A de constante van Arrhenius;
– E de activeringsenergie (in joule per mol);
– T de temperatuur (in kelvin);
– k een getal dat aangeeft hoeveel moleculen er per seconde reageren.$$, 'inline'),
  ('ea041cac-d22c-4e7d-a7f1-d5751a4ec79b', 'e383fe93-6229-4ade-8cb0-22a4ce7dac7b', $$herleide vorm E = 8,314T · ln(A/k)$$,
   $$wiskunde-b-vwo-2017-ii-de-vergelijking-van-arrhenius-context2.png$$,
   $$De vergelijking van Arrhenius kun je herleiden tot de volgende vorm:
E = 8,314T · ln(A/k)$$, 'inline'),
  ('acd5a0a8-02cb-4289-b598-00cd5610ec65', 'e383fe93-6229-4ade-8cb0-22a4ce7dac7b', $$E en A bepalen uit metingen bij twee temperaturen$$,
   $$wiskunde-b-vwo-2017-ii-de-vergelijking-van-arrhenius-context3.png$$,
   $$E en A hebben voor elk soort reactie een eigen waarde. De waarden van E en A hangen niet af van de temperatuur. Omdat ze niet direct te meten zijn, meet men bij een reactie de waarde van k bij twee verschillende temperaturen. Hieruit zijn dan met de vergelijking van Arrhenius de bij die reactie horende waarden van E en A te berekenen.$$, 'inline'),
  ('7dfe8aed-37db-4536-9b08-de1c9d817e67', 'e383fe93-6229-4ade-8cb0-22a4ce7dac7b', $$metingen bij T = 500 en T = 550$$,
   $$wiskunde-b-vwo-2017-ii-de-vergelijking-van-arrhenius-context4.png$$,
   $$Als voorbeeld bekijken we de chemische reactie waarbij stikstofdioxide wordt omgezet naar stikstofmonoxide en zuurstof.
Voor deze reactie is in een proef vastgesteld dat k = 2,7 · 10⁻² als T = 500 en dat k = 2,4 · 10⁻¹ als T = 550.$$, 'inline'),
  ('d5b51978-a964-4468-b299-92028e8c501c', '08415db2-d25c-41e1-a7fa-ca371eae9bfd', $$formules (1) en (2) voor tan(α − β)$$,
   $$wiskunde-b-vwo-2017-ii-een-foto-van-de-eusebiuskerk-context1.png$$,
   $$We bekijken de volgende goniometrische formule:
tan(α − β) = (tan(α) − tan(β))/(1 + tan(α) · tan(β)) (1)
De juistheid van deze formule kan worden bewezen door gebruik te maken van:
tan(α − β) = sin(α − β)/cos(α − β) (2)$$, 'inline'),
  ('cca4a400-697c-42ca-b143-1cb288db532a', '08415db2-d25c-41e1-a7fa-ca371eae9bfd', $$fotograaf en de toren van de Eusebiuskerk$$,
   $$wiskunde-b-vwo-2017-ii-een-foto-van-de-eusebiuskerk-context2.png$$,
   $$Een fotograaf wil de toren van de Eusebiuskerk in Arnhem zo duidelijk mogelijk op de foto krijgen. Hij vraagt zich af op welke afstand van de kerk hij dan moet gaan staan. Deze afstand berekenen we in deze opgave.
foto: de Eusebiuskerk in Arnhem$$, 'inline'),
  ('6bd37f81-b07c-4430-95aa-475c153c2b85', '08415db2-d25c-41e1-a7fa-ca371eae9bfd', $$schematische situatie met kijkhoek φ$$,
   $$wiskunde-b-vwo-2017-ii-een-foto-van-de-eusebiuskerk-context3.png$$,
   $$In figuur 1, op de volgende bladzijde, is de situatie schematisch weergegeven. Punt A is een punt aan de voet van de toren. De punten B en C liggen beide recht boven punt A. Punt B ligt op een hoogte van 27 meter boven A. Punt C ligt op een hoogte van 75 meter boven A. De fotograaf staat bij punt P op een afstand van x meter van A. Hij zet zijn camera in P op de grond zó dat alleen het deel van de toren tussen B en C op de foto staat. Er geldt: ∠PAB = 90°. Verder is α = ∠APC, β = ∠APB en φ = α − β. We noemen φ de kijkhoek.$$, 'inline'),
  ('22bdbe4e-ee90-451e-89c0-b1f48dd61c2a', '08415db2-d25c-41e1-a7fa-ca371eae9bfd', $$figuur 1$$,
   $$wiskunde-b-vwo-2017-ii-een-foto-van-de-eusebiuskerk-context4.png$$,
   $$figuur 1: schematische weergave met de punten P, A, B (27 m) en C (75 m), afstand x en de hoeken α, β en φ$$, 'inline'),
  ('9e7f4d7a-614a-4e43-8fe7-97e784aa8603', '08415db2-d25c-41e1-a7fa-ca371eae9bfd', $$formule (3): tan(φ) uitgedrukt in x$$,
   $$wiskunde-b-vwo-2017-ii-een-foto-van-de-eusebiuskerk-context5.png$$,
   $$Door gebruik te maken van formule 1 is het mogelijk tan(φ) uit te drukken in x. Er geldt:
tan(φ) = 48x/(x² + 2025) (3)$$, 'inline'),
  ('9892a067-c244-440f-8b0f-253adbd4776d', '08415db2-d25c-41e1-a7fa-ca371eae9bfd', $$grafiek van g(x) = 48x/(x² + 2025) (figuur 2)$$,
   $$wiskunde-b-vwo-2017-ii-een-foto-van-de-eusebiuskerk-context6.png$$,
   $$In figuur 2 is de grafiek van de functie g met functievoorschrift g(x) = 48x/(x² + 2025) geschetst.
figuur 2: grafiek van g$$, 'inline'),
  ('0c62490e-12a2-47fc-8ff2-cacaad949d3f', '08415db2-d25c-41e1-a7fa-ca371eae9bfd', $$kijkhoek φ maximaal$$,
   $$wiskunde-b-vwo-2017-ii-een-foto-van-de-eusebiuskerk-context7.png$$,
   $$Om het deel van de toren tussen B en C zo duidelijk mogelijk op de foto te krijgen, moet kijkhoek φ maximaal zijn. Dat is het geval als tan(φ) maximaal is. In figuur 2 is te zien dat er een waarde van x bestaat waarvoor g(x) en dus tan(φ) maximaal is.$$, 'inline'),
  ('ba62ff5b-3670-4a6e-8d1e-41ba9de4b5ee', '4e81170c-049a-4074-a13f-6b0271d6bfee', $$bewegingsvergelijkingen van P met parameter a$$,
   $$wiskunde-b-vwo-2017-ii-scheve-parabolen-context1.png$$,
   $$Voor a > 0 is de baan van het punt P gegeven door de volgende bewegingsvergelijkingen:
x(t) = at² + t + 1
y(t) = at² − t + 1
waarbij t de tijd voorstelt.$$, 'inline'),
  ('1d8cb078-c933-4b70-8b05-011340d7a6ee', '4e81170c-049a-4074-a13f-6b0271d6bfee', $$a = 3 en minimale snelheid$$,
   $$wiskunde-b-vwo-2017-ii-scheve-parabolen-context2.png$$,
   $$Neem a = 3. Dan zijn de bewegingsvergelijkingen van P dus:
x(t) = 3t² + t + 1
y(t) = 3t² − t + 1
Voor a = 3 is de snelheid van P op zeker moment minimaal.$$, 'inline'),
  ('67d7a456-bd44-42e1-8bc6-17ad991699f6', '4e81170c-049a-4074-a13f-6b0271d6bfee', $$banen voor twee waarden van a (figuur)$$,
   $$wiskunde-b-vwo-2017-ii-scheve-parabolen-context3.png$$,
   $$De baan van P is voor elke waarde van a > 0 een scheve parabool. In de figuur is voor twee waarden van a de baan van P weergegeven.
figuur: de banen van P voor a = 2 en a = 0,12$$, 'inline'),
  ('4d5e3149-29af-4499-8aa4-cf13708b3e8c', '4e81170c-049a-4074-a13f-6b0271d6bfee', $$P op de x-as$$,
   $$wiskunde-b-vwo-2017-ii-scheve-parabolen-context4.png$$,
   $$Voor a = 0,12 bevindt P zich op twee tijdstippen op de x-as. Voor a = 2 is er geen enkel tijdstip waarop P zich op de x-as bevindt. Zie de figuur. Er is één waarde van a waarvoor P zich op precies één tijdstip op de x-as bevindt.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('63dfbaef-286b-4dc2-9335-de04192de8db', 'ceb32f3a-012d-47b9-a2ea-7a5b65a11924', 1,
   '[{"domain": "Differentiaal- en integraalrekening", "subdomain": "Afgeleide functies"}, {"domain": "Differentiaal- en integraalrekening", "subdomain": "Technieken voor differentiëren"}, {"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Vergelijkingen en ongelijkheden"}]'::jsonb,
   '["minimum", "afgeleide van exponentiële functie", "kettingregel", "exponentiële vergelijking", "exact berekenen"]'::jsonb,
   $$Exact berekenen waar een som van exponentiële functies minimaal is met de afgeleide.$$,
   $$wiskunde-b-vwo-2017-ii-twee-machten-van-2-vraag1.png$$, $$5p 1 Bereken exact de waarde van x waarvoor f(x) minimaal is.$$, array['fa781c83-0ced-4d56-a331-02766ca122a9']::uuid[]),
  ('7d43112c-8aaa-4fda-a8c3-287272572e27', 'ceb32f3a-012d-47b9-a2ea-7a5b65a11924', 2,
   '[{"domain": "Differentiaal- en integraalrekening", "subdomain": "Integraalrekening"}]'::jsonb,
   '["oppervlakte onder grafiek", "primitieve van exponentiële functie", "bepaalde integraal", "algebraïsch berekenen"]'::jsonb,
   $$Algebraïsch berekenen van de hoogte van een rechthoek met dezelfde oppervlakte als een vlakdeel onder een exponentiële grafiek.$$,
